mapper.select:
SELECT op.OPEN_VDATE
FROM FIN_OPEN_PLAN op
WHERE op.FINPROD_ID = #{finProdId,jdbcType=VARCHAR}
AND DATE_FORMAT(op.OPEN_DATE_STR,'%Y%m%d') = #{startdate,jdbcType=VARCHAR}
AND DATE_FORMAT(op.OPEN_DATE_END,'%Y%m%d') = #{enddate,jdbcType=VARCHAR}

   SELECT  deal.totle_trade_id
 FROM TRD_FIN_PRODUCT_DEAL_TOTAL deal,
      PA_TRD_FIN_PRODUCT_DEAL_TOTAL  padeal
WHERE deal.FINPROD_ID = #{finProdId,jdbcType=VARCHAR}
       AND padeal.PA_BUSS_TYPE = #{pabussType,jdbcType=VARCHAR}
       AND deal.PS = #{tradePS,jdbcType=VARCHAR}
       AND padeal.totle_trade_id=deal.totle_trade_id
       AND DATE_FORMAT(deal.VDATE, '%Y%m%d') = #{vdate,jdbcType=VARCHAR}
       AND deal.TRADE_STATUS <> '03'
       AND deal.IS_CANCEL = 'N'
